def transform(grid):
    # Fill each zero from the cyclic sequence indicated by the closest nonzero
    # cells along its row (row contains several phase-shifted intact stretches).
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]: continue
            opts=[]
            for j,v in enumerate(grid[r]):
                if v:
                    expected=((v-1+c-j)%9)+1
                    opts.append((abs(c-j),expected))
            if opts:
                out[r][c]=min(opts)[1]
    return out

